class Solution(object):
    def modifiedGraphEdges(self, n, edges, source, destination, target):
        """
        :type n: int
        :type edges: List[List[int]]
        :type source: int
        :type destination: int
        :type target: int
        :rtype: List[List[int]]
        """
        def dijkstra(edges):
            g = [[float("inf")] * n for _ in range(n)]
            for x, y, w in edges:
                if w != -1:
                    g[x][y] = g[y][x] = w
            dist = [float("inf")] * n
            dist[source] = 0
            vis = [False] * n
            for _ in range(n):
                k = -1
                min_dist = float("inf")
                for j in range(n):
                    if not vis[j] and dist[j] < min_dist:
                        min_dist = dist[j]
                        k = j
                vis[k] = True
                for j in range(n):
                    dist[j] = min(dist[j], dist[k] + g[k][j])
            return dist[destination]

        d = dijkstra(edges)
        if d < target:
            return []
        flag = False
        if d == target:
            flag = True
        for e in edges:
            if e[2] > 0:
                continue
            if flag:
                e[2] = 2 * 10 ** 9
                continue
            e[2] = 1
            d = dijkstra(edges)
            if d <= target:
                flag = True
                e[2] += target - d
        return edges if flag else []
